#!/usr/bin/env bash
# orion-boardroom: the sign-off station VM (Appendix A.6 of docs/NEXT_PASS_PLAN.md).
#
#   sudo bash boardroom-setup.sh
#
# Result:
#   - only root services (Tailscale itself, apt security updates) may reach the internet;
#     your user can only talk over the Tailscale network (Tailscale ACLs: the PC's daemon only)
#   - console auto-locks after 5 minutes idle
#   - minisign installed; the boardroom key is generated by YOU afterwards (it asks for a passphrase)
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=common-harden.sh
source "$HERE/common-harden.sh"
require_root

harden_base orion-boardroom
export DEBIAN_FRONTEND=noninteractive
apt-get install -y -q python3.12-venv minisign vlock

ADMIN="$(admin_user)"
ADMIN_HOME="$(getent passwd "$ADMIN" | cut -d: -f6)"
install -d -m 700 -o "$ADMIN" -g "$ADMIN" "$ADMIN_HOME/.orion-boardroom"

# ---------------------------------------------------------------- egress: user traffic only over Tailscale
# (Blocking *all* outgoing traffic with ufw would also cut Tailscale's own control connection, so instead:
#  root — tailscaled and apt — may go out; every other user may only use loopback and the tailscale0 interface.)
log "Restricting outgoing traffic to the private VPN…"
APT_UID="$(id -u _apt 2>/dev/null || echo 0)"
cat >/etc/nftables-orion.conf <<EOF
#!/usr/sbin/nft -f
table inet orion_egress
delete table inet orion_egress
table inet orion_egress {
  chain output {
    type filter hook output priority 0; policy accept;
    meta skuid 0 accept
    meta skuid $APT_UID accept
    oif lo accept
    oifname "tailscale0" accept
    counter reject
  }
}
EOF
cat >/etc/systemd/system/orion-egress.service <<'EOF'
[Unit]
Description=Orion boardroom egress rules (users may only use the Tailscale network)
After=network-pre.target
Before=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/usr/sbin/nft -f /etc/nftables-orion.conf
ExecStop=/usr/sbin/nft delete table inet orion_egress

[Install]
WantedBy=multi-user.target
EOF
systemctl daemon-reload
systemctl enable --now orion-egress.service >/dev/null
systemctl restart orion-egress.service

# ---------------------------------------------------------------- auto-lock and logout
log "Console auto-logout after 5 minutes idle…"
cat >/etc/profile.d/orion-autolock.sh <<'EOF'
# Orion boardroom: idle shells log out after 5 minutes
TMOUT=300
readonly TMOUT
export TMOUT
EOF
# lock virtual consoles with vlock when the session goes idle is handled by TMOUT; use `vlock -a` to lock manually.

# ---------------------------------------------------------------- remove things a sign-off station doesn't need
for pkg in firefox chromium-browser snapd; do
  if dpkg -s "$pkg" >/dev/null 2>&1; then apt-get purge -y -q "$pkg" || true; fi
done

log "orion-boardroom is set up."
cat <<EOF

Next steps (run these yourself, as $ADMIN, not with sudo):
  1. Make the boardroom key — it asks for a passphrase; pick a long one and never reuse it:
       minisign -G -p ~/.orion-boardroom/boardroom.pub -s ~/.orion-boardroom/boardroom.key
  2. Copy ONLY boardroom.pub to the PC (Orion settings). The private key never leaves this machine.
  3. Back up boardroom.key to an encrypted USB stick you keep offline.
  4. In the Tailscale admin console: tag this machine  tag:boardroom , disable key expiry, apply the ACL.
  5. Run the checklist:   bash $HERE/verify-boardroom.sh
  6. In your hypervisor, take a snapshot named  boardroom-ready
EOF
